/**
 * test-schema-mapping.js — offline harness for the Phase 6 session-2 schema
 * mapping layer (src/schema.js + the slimGCItem attribute reads in
 * src/steam-gc.js).
 *
 * No network: runs entirely against the bundled snapshot
 * (assets/schema-snapshot.json), which is generated by the SAME distiller the
 * runtime fetch path uses, so passing here validates the composition rules
 * end-to-end.
 *
 * Run: node test-schema-mapping.js
 */

const fs = require('fs');
const path = require('path');
const schema = require('./src/schema.js');
const gc = require('./src/steam-gc.js');

const snap = JSON.parse(fs.readFileSync(path.join(__dirname, 'assets', 'schema-snapshot.json'), 'utf8'));

let pass = 0, fail = 0;
function assert(label, actual, expected) {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a === e) { pass++; console.log('  ✓ ' + label); }
  else { fail++; console.log('  ✗ ' + label + '\n      expected ' + e + '\n      got      ' + a); }
}

// Convenience: build a slim item with defaults
function slim(over) {
  return Object.assign({
    id: '1', defIndex: 0, paintIndex: null, paintWear: null, quality: 4,
    rarity: null, customName: null, stickerCount: 0, statTrak: false,
    stickerKitId: null, musicId: null, keychainId: null, graffitiTint: null,
  }, over);
}
function nameOf(over) {
  const r = schema.resolveGCItem(slim(over), snap);
  return r ? r.name : null;
}
function resOf(over) { return schema.resolveGCItem(slim(over), snap); }

console.log('— Wear brackets (boundary values are min-inclusive of the next bracket)');
assert('0.00 → Factory New', schema.wearName(0.0), 'Factory New');
assert('0.0699 → Factory New', schema.wearName(0.0699), 'Factory New');
assert('0.07 → Minimal Wear', schema.wearName(0.07), 'Minimal Wear');
assert('0.1499 → Minimal Wear', schema.wearName(0.1499), 'Minimal Wear');
assert('0.15 → Field-Tested', schema.wearName(0.15), 'Field-Tested');
assert('0.3799 → Field-Tested', schema.wearName(0.3799), 'Field-Tested');
assert('0.38 → Well-Worn', schema.wearName(0.38), 'Well-Worn');
assert('0.4499 → Well-Worn', schema.wearName(0.4499), 'Well-Worn');
assert('0.45 → Battle-Scarred', schema.wearName(0.45), 'Battle-Scarred');
assert('1.00 → Battle-Scarred', schema.wearName(1.0), 'Battle-Scarred');
assert('null wear → null', schema.wearName(null), null);

console.log('— Live fixtures from the "Clutch and TUFS" unit (v3.7.0 field test)');
assert('def 4471 (no paint) → Clutch Case', nameOf({ defIndex: 4471 }), 'Clutch Case');
assert('def 8 · paint 121 → AUG | Luxe Trim (FT)', nameOf({ defIndex: 8, paintIndex: 121, paintWear: 0.2 }), 'AUG | Luxe Trim (Field-Tested)');
assert('def 14 · paint 120 → M249 | Hypnosis (MW)', nameOf({ defIndex: 14, paintIndex: 120, paintWear: 0.09 }), 'M249 | Hypnosis (Minimal Wear)');
assert('def 38 · paint 117 → SCAR-20 | Trail Blazer (FN)', nameOf({ defIndex: 38, paintIndex: 117, paintWear: 0.03 }), 'SCAR-20 | Trail Blazer (Factory New)');
// The fixture note said "def 23 · paint 1100" but paint kit 1100
// (cu_glock_snackattack) pairs only with weapon_glock (def 4) in items_game —
// the canonical item is the Glock. The mapper composes faithfully either way.
assert('def 4 · paint 1100 → Glock-18 | Snack Attack (MW)', nameOf({ defIndex: 4, paintIndex: 1100, paintWear: 0.1 }), 'Glock-18 | Snack Attack (Minimal Wear)');
assert('def 23 · paint 1100 composes off def 23 (MP5-SD) faithfully', nameOf({ defIndex: 23, paintIndex: 1100, paintWear: 0.1 }), 'MP5-SD | Snack Attack (Minimal Wear)');

console.log('— StatTrak™ / Souvenir prefixes');
assert('StatTrak weapon', nameOf({ defIndex: 7, paintIndex: 44, paintWear: 0.2, statTrak: true }), 'StatTrak™ AK-47 | ' + snap.paints['44'].n + ' (Field-Tested)');
assert('Souvenir weapon (quality 12)', nameOf({ defIndex: 9, paintIndex: 51, paintWear: 0.05, quality: 12 }), 'Souvenir AWP | ' + snap.paints['51'].n + ' (Factory New)');
assert('StatTrak wins over quality (mutually exclusive in practice)', nameOf({ defIndex: 7, paintIndex: 44, paintWear: 0.2, statTrak: true, quality: 12 }), 'StatTrak™ AK-47 | ' + snap.paints['44'].n + ' (Field-Tested)');

console.log('— Knives: ★ prefix, vanilla, StatTrak, Doppler phases');
assert('painted knife', nameOf({ defIndex: 507, paintIndex: 12, paintWear: 0.2, quality: 3 }), '★ Karambit | ' + snap.paints['12'].n + ' (Field-Tested)');
assert('vanilla knife (no paint, no wear)', nameOf({ defIndex: 500, paintIndex: null, quality: 3 }), '★ Bayonet');
assert('vanilla knife with paintIndex 0', nameOf({ defIndex: 500, paintIndex: 0, quality: 3 }), '★ Bayonet');
assert('StatTrak vanilla knife', nameOf({ defIndex: 500, paintIndex: null, quality: 3, statTrak: true }), '★ StatTrak™ Bayonet');
assert('StatTrak painted knife', nameOf({ defIndex: 507, paintIndex: 12, paintWear: 0.06, quality: 3, statTrak: true }), '★ StatTrak™ Karambit | ' + snap.paints['12'].n + ' (Factory New)');
assert('Doppler market hash has NO phase', nameOf({ defIndex: 507, paintIndex: 419, paintWear: 0.02, quality: 3 }), '★ Karambit | Doppler (Factory New)');
assert('Doppler paint 419 → Phase 2 (separate field)', resOf({ defIndex: 507, paintIndex: 419, paintWear: 0.02, quality: 3 }).phase, 'Phase 2');
assert('Doppler paint 415 → Ruby', resOf({ defIndex: 507, paintIndex: 415, paintWear: 0.02, quality: 3 }).phase, 'Ruby');
assert('Doppler paint 416 → Sapphire', resOf({ defIndex: 507, paintIndex: 416, paintWear: 0.02, quality: 3 }).phase, 'Sapphire');
assert('Doppler paint 417 → Black Pearl', resOf({ defIndex: 507, paintIndex: 417, paintWear: 0.02, quality: 3 }).phase, 'Black Pearl');
assert('Gamma Doppler paint 568 → Emerald', resOf({ defIndex: 507, paintIndex: 568, paintWear: 0.02, quality: 3 }).phase, 'Emerald');
assert('Gamma Doppler paint 572 → Phase 4', resOf({ defIndex: 507, paintIndex: 572, paintWear: 0.02, quality: 3 }).phase, 'Phase 4');
assert('Glock Gamma Doppler paint 1120 → Phase 1', resOf({ defIndex: 4, paintIndex: 1120, paintWear: 0.02 }).phase, 'Phase 1');
assert('non-Doppler paint → phase null', resOf({ defIndex: 507, paintIndex: 12, paintWear: 0.2, quality: 3 }).phase, null);

console.log('— Gloves');
assert('gloves get ★', nameOf({ defIndex: 5032, paintIndex: 10010, paintWear: 0.3 }), '★ Hand Wraps | Spruce DDPAT (Field-Tested)');

console.log('— Stickers / patches / graffiti (kit id from attribute 113)');
assert('sticker kit 76', nameOf({ defIndex: 1209, stickerKitId: 76 }), 'Sticker | Titan (Holo) | Katowice 2014');
assert('sticker with no kit id → unmapped', nameOf({ defIndex: 1209, stickerKitId: null }), null);
const patchKit = Object.keys(snap.stickers).find(function (k) { return true; });
assert('patch composes "Patch | …"', nameOf({ defIndex: 4609, stickerKitId: Number(patchKit) }), 'Patch | ' + snap.stickers[patchKit]);
assert('sealed graffiti with tint', nameOf({ defIndex: 1348, stickerKitId: 1, graffitiTint: 1 }), 'Sealed Graffiti | ' + snap.stickers['1'] + ' (Brick Red)');
assert('sealed graffiti without tint', nameOf({ defIndex: 1348, stickerKitId: 1, graffitiTint: null }), 'Sealed Graffiti | ' + snap.stickers['1']);

console.log('— Charms / music kits (armory-era items)');
assert('charm keychain 1', nameOf({ defIndex: 1355, keychainId: 1 }), "Charm | Lil' Ava");
assert('charm with no id → unmapped', nameOf({ defIndex: 1355, keychainId: null }), null);
assert('music kit 3', nameOf({ defIndex: 1314, musicId: 3 }), 'Music Kit | Daniel Sadowski, Crimson Assault');
assert('StatTrak music kit', nameOf({ defIndex: 1314, musicId: 3, statTrak: true }), 'StatTrak™ Music Kit | Daniel Sadowski, Crimson Assault');

console.log('— Agents (name verbatim from schema, incl. Steam\'s double-space quirk)');
assert('agent 5105', nameOf({ defIndex: 5105 }), 'Ground Rebel  | Elite Crew');

console.log('— Unknowns / fallbacks');
assert('unknown defindex → null (renderer falls back to raw)', nameOf({ defIndex: 999999 }), null);
assert('known weapon + unknown paint → null', nameOf({ defIndex: 7, paintIndex: 999999, paintWear: 0.2 }), null);
assert('null schema → null', schema.resolveGCItem(slim({ defIndex: 4471 }), null), null);
assert('painted weapon with missing wear float → name without bracket', nameOf({ defIndex: 8, paintIndex: 121, paintWear: null }), 'AUG | Luxe Trim');

console.log('— slimGCItem attribute reads (raw GC item shapes)');
function u32(v) { const b = Buffer.alloc(4); b.writeUInt32LE(v, 0); return b; }
const rawSticker = { id: 1, def_index: 1209, attribute: [{ def_index: 113, value_bytes: u32(76) }] };
assert('sticker tool: kit from attr 113', gc.slimGCItem(rawSticker).stickerKitId, 76);
const rawStickerParsed = { id: 2, def_index: 1209, stickers: [{ slot: 0, sticker_id: 76 }] };
assert('sticker tool: kit fallback from parsed stickers[]', gc.slimGCItem(rawStickerParsed).stickerKitId, 76);
const rawWeaponWithSticker = { id: 3, def_index: 7, paint_index: 44, paint_wear: 0.2, stickers: [{ slot: 0, sticker_id: 76 }] };
assert('weapon with APPLIED sticker: stickerKitId stays null', gc.slimGCItem(rawWeaponWithSticker).stickerKitId, null);
assert('weapon with APPLIED sticker: stickerCount preserved', gc.slimGCItem(rawWeaponWithSticker).stickerCount, 1);
const rawMusic = { id: 4, def_index: 1314, attribute: [{ def_index: 166, value_bytes: u32(3) }] };
assert('music kit: id from attr 166', gc.slimGCItem(rawMusic).musicId, 3);
const rawCharm = { id: 5, def_index: 1355, attribute: [{ def_index: 299, value_bytes: u32(1) }] };
assert('charm: id from attr 299', gc.slimGCItem(rawCharm).keychainId, 1);
const rawGraffiti = { id: 6, def_index: 1348, attribute: [{ def_index: 113, value_bytes: u32(1) }, { def_index: 233, value_bytes: u32(1) }] };
const sg = gc.slimGCItem(rawGraffiti);
assert('graffiti: kit + tint read', [sg.stickerKitId, sg.graffitiTint], [1, 1]);
assert('attr reader: Uint8Array value_bytes tolerated', gc.readU32Attr({ attribute: [{ def_index: 166, value_bytes: new Uint8Array([3, 0, 0, 0]) }] }, 166), 3);
assert('attr reader: short buffer → null', gc.readU32Attr({ attribute: [{ def_index: 166, value_bytes: Buffer.from([1]) }] }, 166), null);
assert('attr reader: missing attr → null', gc.readU32Attr({ attribute: [] }, 166), null);

console.log('— End-to-end: raw GC item → slim → resolve');
const rawKnife = { id: 7, def_index: 507, paint_index: 418, paint_wear: 0.032, quality: 3, kill_eater_value: 55 };
const rk = schema.resolveGCItem(gc.slimGCItem(rawKnife), snap);
assert('StatTrak Karambit Doppler P1 FN', [rk.name, rk.phase], ['★ StatTrak™ Karambit | Doppler (Factory New)', 'Phase 1']);
const rawCase = { id: 8, def_index: 4471 };
assert('Clutch Case end-to-end', schema.resolveGCItem(gc.slimGCItem(rawCase), snap).name, 'Clutch Case');

console.log('— Distiller sanity on the snapshot itself');
assert('snapshot has schema version', snap.v, 1);
assert('storage unit def 1201 resolves (never shown, but mapped)', typeof snap.items['1201'].n, 'string');
assert('paint 0 excluded from paints (vanilla path)', snap.paints['0'], undefined);
assert('phaseFromKitName: am_doppler_phase3', schema.phaseFromKitName('am_doppler_phase3'), 'Phase 3');
assert('phaseFromKitName: non-doppler → null', schema.phaseFromKitName('cu_m4a1_hydra'), null);

console.log('\n' + pass + '/' + (pass + fail) + ' assertions passed' + (fail ? ' — ' + fail + ' FAILED' : ''));
process.exit(fail ? 1 : 0);
